{"witnessCode": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import normalizeUrl from '../index.js';

test('stripWWW should not remove www from hostname with empty label', t => {
  const input = 'http://www..example.com';
  const options = { stripWWW: true };
  const expected = 'http://www..example.com';
  const actual = normalizeUrl(input, options);
  assert.strictEqual(actual, expected);
});"}
